xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght=1,300&family=Noto+Serif+SC:wght=300;400;600&family=Space+Mono&display=swap');
@import url("https://fontsapi.zeoseven.com/53/main/result.css");
@import url("https://fontsapi.zeoseven.com/282/main/result.css");

/* === 整个大框架：柔和樱花暖粉色系 === */
.xt-root {
  --xt-bg: #fdf5f6; /* 极其温和浅淡的樱花暖粉色 */
  --xt-text: #5a444a; /* 轻柔的冷调莓灰褐，无刺眼深色 */
  --xt-text-sub: #d49da8; /* 温柔的雾面浅粉色 */
  --xt-accent: #e5b3be; /* 核心温润淡粉色 */
  --xt-accent-light: #f9eaec;
  --xt-font: 'Noto Serif SC', serif; 

  /* 精确缩减底栏，刚好贴合下方的英文字母与重叠圆圈 */
  padding: 16px 12px 28px !important; 
  position: relative;
  border-radius: 12px;

  /* 稳定最大高度约束，展开时卡片骨架不向下延展 */
  max-height: 600px !important; 
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch;

  /* 隐藏外边框滑动条 */
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;

  /* 拓宽两边比例 */
  width: 92% !important;
  margin-left: auto !important;
  margin-right: auto !important;

  /* 极浅暖粉色时间轴线 */
  background: 
    linear-gradient(to bottom, transparent 30px, rgba(229, 179, 190, 0.12) 30px, rgba(229, 179, 190, 0.12) calc(100% - 30px), transparent calc(100% - 30px)) no-repeat right 22px top 0px / 1px 100%,
    var(--xt-bg) !important;
}

/* === 层级 0：完美更替为落落大方落樱柔粉背景图 === */
.xt-root::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 340px; 
  background: url('https://i.postimg.cc/jj1FjL4v/quality-restoration-20260802202353054.jpg') center 40% / cover no-repeat;
  mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 35%, rgba(0,0,0,0) 100%);
  -webkit-mask-image: linear-gradient(to bottom, rgba(0,0,0,1) 35%, rgba(0,0,0,0) 100%);
  z-index: 0;
  opacity: 0.95;
}

/* 隐藏粒子 */
.xt-particles { 
  display: none !important; 
}

/* 隐藏指示器 */
.xt-collapse-arrow {
  display: none !important;
}

/* 顶部海报排版 */
.xt-root::after {
  content: "● ● \A C H E R R Y   M I S T   J O U R N A L \A F R A G M E N T S \A S H A N G H A I \A E C H O E S";
  position: absolute;
  top: 20px; left: 24px;
  font-family: 'Space Mono', monospace;
  font-size: 8px;
  color: rgba(90, 68, 74, 0.65);
  white-space: pre-wrap;
  line-height: 1.8;
  z-index: 1;
}

/* 极其淡雅的柔粉色英文诗句 */
.xt-content::after {
  content: "MISTY DROPS DRIFT SILENTLY ACROSS THE BLUE WINDOW \A WEAVING THE QUIET SECRETS OF OUR SHARED HOURS \A EVEN IN THE FAINT CHILL OF THIS FAINT DAY \A I AM SEARCHING FOR YOUR SHADOW IN THE RAIN" !important;
  display: block;
  font-family: 'Space Mono', monospace;
  font-size: 8px;
  color: rgba(229, 179, 190, 0.18) !important; 
  white-space: pre;
  line-height: 1.5;
  margin-top: 4px; 
  padding-bottom: 0;
  transform: scale(0.95);
  transform-origin: left top;
  order: 5 !important; 
}

/* 内容区 */
.xt-content { 
  position: relative; 
  z-index: 2; 
  padding-top: 160px; 
  transform: scale(0.95); 
  transform-origin: center top;
  display: flex;
  flex-direction: column;
}

/* 右侧垂直时间 */
.xt-content::before {
  content: "2 0 2 6 . 0 5 . 2 1  ●" !important;
  position: absolute !important;
  right: -16px !important; 
  top: 155px !important;
  font-family: 'Space Mono', monospace !important;
  font-size: 7px !important;
  font-weight: 500 !important;
  color: rgba(229, 179, 190, 0.45) !important;
  writing-mode: vertical-rl !important; 
  text-orientation: mixed !important;
  letter-spacing: 5px !important;
  z-index: 10 !important;
  pointer-events: none !important;
  opacity: 0.8;
}

/* === 抽屉骨架 === */
.xt-collapse {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  border-bottom: 1px solid rgba(229, 179, 190, 0.1) !important; 
  border-radius: 0px !important; 
  transition: none !important;
  position: relative;
}

.xt-collapse-2 { 
  order: 1; z-index: 3; 
  margin-left: 8px !important; margin-right: 28px !important; 
  border-left: 1px solid rgba(229, 179, 190, 0.12) !important; 
  background: transparent !important; 
  box-shadow: 0 -3px 8px rgba(90, 68, 74, 0.02) !important; 
}
.xt-collapse-1 { 
  order: 2; z-index: 2; 
  margin-left: 18px !important; margin-right: 38px !important; margin-top: -12px !important; 
  border-left: 1px solid rgba(229, 179, 190, 0.18) !important; 
  background: transparent !important; 
  box-shadow: 0 -3px 10px rgba(90, 68, 74, 0.03) !important;
}
.xt-collapse-3 { 
  order: 3; z-index: 1; 
  margin-left: 28px !important; margin-right: 48px !important; margin-top: -12px !important; 
  border-left: 1px solid rgba(229, 179, 190, 0.24) !important; 
  background: transparent !important; 
  box-shadow: 0 -3px 12px rgba(90, 68, 74, 0.04) !important;
}

/* 避让逻辑 */
#xt-t2:checked ~ .xt-content .xt-collapse-1,
#xt-t2:checked ~ .xt-content .xt-collapse-3 {
  margin-top: 20px !important;
}
#xt-t1:checked ~ .xt-content .xt-collapse-3 {
  margin-top: 20px !important;
}

/* 标题线条 */
.xt-collapse-header {
  height: 68px !important; 
  display: flex; align-items: center;
  font-family: var(--xt-font) !important; 
  background: transparent;
  white-space: nowrap; overflow: hidden;
  transition: all 0.3s;
  color: transparent !important; 

  background: linear-gradient(to right, transparent 190px, rgba(229, 179, 190, 0.16) 190px, transparent 260px) no-repeat left 50% / 100% 1px !important;
  border-bottom: none !important;

  backdrop-filter: blur(1.5px) !important;
  -webkit-backdrop-filter: blur(1.5px) !important;
  mask-image: linear-gradient(to right, rgba(0,0,0,1) 45%, rgba(0,0,0,0.3) 75%, rgba(0,0,0,0.95) 100%) !important;
  -webkit-mask-image: linear-gradient(to right, rgba(0,0,0,1) 45%, rgba(0,0,0,0.3) 75%, rgba(0,0,0,0.95) 100%) !important;
}

/* ====================================================
   🔥 阶梯互锁中文标题 (柔粉色阴影化)
==================================================== */
.xt-collapse-2 .xt-collapse-header::before {
  content: "隙\3000碎\3000光" !important;
  position: absolute; left: 8px; top: 12px;
  font-size: 23px !important; font-weight: 600;
  color: rgba(90, 68, 74, 0.45) !important; 
  letter-spacing: 12px !important;
  transform: rotate(1deg);
  font-family: var(--xt-font) !important;
  text-shadow: 0 0 2px rgba(90, 68, 74, 0.1), 0 0 10px rgba(255, 255, 255, 0.8) !important;
}
.xt-collapse-2 .xt-collapse-header::after {
  content: "\3000 間\3000 落\3000 陰" !important;
  position: absolute; left: 8px; top: 18px;
  font-size: 16px !important; font-weight: 400;
  color: rgba(229, 179, 190, 0.38) !important; 
  letter-spacing: 20px !important;
  transform: rotate(-2deg);
  font-family: var(--xt-font) !important;
  text-shadow: 0 0 3px rgba(229, 179, 190, 0.1), 0 0 10px rgba(255, 255, 255, 0.8) !important;
}

.xt-collapse-1 .xt-collapse-header::before {
  content: "紙\3000情\3000啓" !important; 
  position: absolute; left: 8px; top: 12px;
  font-size: 23px !important; font-weight: 600;
  color: rgba(90, 68, 74, 0.45) !important; 
  letter-spacing: 12px !important; 
  transform: rotate(-1.5deg);
  font-family: var(--xt-font) !important;
  text-shadow: 0 0 2px rgba(90, 68, 74, 0.1), 0 0 10px rgba(255, 255, 255, 0.8) !important;
}
.xt-collapse-1 .xt-collapse-header::after {
  content: "\3000 短\3000 長" !important; 
  position: absolute; left: 8px; top: 18px;
  font-size: 15px !important; font-weight: 400;
  color: rgba(229, 179, 190, 0.38) !important; 
  letter-spacing: 20px !important; 
  transform: rotate(2deg);
  font-family: var(--xt-font) !important;
  text-shadow: 0 0 3px rgba(229, 179, 190, 0.1), 0 0 10px rgba(255, 255, 255, 0.8) !important;
}

.xt-collapse-3 .xt-collapse-header::before {
  content: "浮\3000生\3000瑣" !important; 
  position: absolute; left: 8px; top: 11px;
  font-size: 23px !important; font-weight: 600;
  color: rgba(90, 68, 74, 0.45) !important; 
  letter-spacing: 12px !important;
  transform: rotate(-2deg);
  font-family: var(--xt-font) !important;
  text-shadow: 0 0 2px rgba(90, 68, 74, 0.1), 0 0 10px rgba(255, 255, 255, 0.8) !important;
}
.xt-collapse-3 .xt-collapse-header::after {
  content: "\3000 瑣\3000 記" !important;
  position: absolute; left: 8px; top: 18px;
  font-size: 16px !important; font-weight: 400;
  color: rgba(229, 179, 190, 0.38) !important; 
  letter-spacing: 20px !important;
  transform: rotate(2.5deg);
  font-family: var(--xt-font) !important;
  text-shadow: 0 0 3px rgba(229, 179, 190, 0.1), 0 0 10px rgba(255, 255, 255, 0.8) !important;
}

/* 英文副标 */
.xt-collapse-2::before { content: "E C H O   O F   T I N Y   W H I S P E R S" !important; position: absolute; left: 8px; top: 41px; font-family: 'Space Mono', monospace; font-size: 7.5px; color: var(--xt-text-sub); opacity: 0.35; letter-spacing: 0.8px; z-index: 5; pointer-events: none; }
.xt-collapse-1::before { content: "A   L E T T E R   F R O M   T H E   B L U E" !important; position: absolute; left: 8px; top: 41px; font-family: 'Space Mono', monospace; font-size: 7.5px; color: var(--xt-text-sub); opacity: 0.35; letter-spacing: 0.8px; z-index: 5; pointer-events: none; }
.xt-collapse-3::before { content: "S C R I B B L E S   I N   D A I L Y   L I F E" !important; position: absolute; left: 8px; top: 41px; font-family: 'Space Mono', monospace; font-size: 7.5px; color: var(--xt-text-sub); opacity: 0.35; letter-spacing: 0.8px; z-index: 5; pointer-events: none; }

/* === 滴水物理滑坠特效 === */
@keyframes drip {
  0% { transform: translateY(-30px) scaleY(0.9); opacity: 0; }
  20% { opacity: 0.45; }
  75% { transform: translateY(160px) scaleY(1.15); opacity: 0; }
  100% { transform: translateY(160px) scaleY(0.9); opacity: 0; }
}
.xt-collapse-body::before { content: "" !important; position: absolute !important; top: 0 !important; left: 18% !important; width: 1px !important; height: 16px !important; background: linear-gradient(to bottom, rgba(229, 179, 190, 0.35), rgba(229, 179, 190, 0)) !important; animation: drip 4.2s infinite linear !important; pointer-events: none !important; z-index: 0 !important; }
.xt-collapse-body::after { content: "" !important; position: absolute !important; top: 0 !important; right: 22% !important; width: 1px !important; height: 16px !important; background: linear-gradient(to bottom, rgba(229, 179, 190, 0.35), rgba(229, 179, 190, 0)) !important; animation: drip 4.8s infinite linear 2.1s !important; pointer-events: none !important; z-index: 0 !important; }

/* 收起状态 */
.xt-collapse-body {
  padding: 0 20px !important; opacity: 0; visibility: hidden; 
  max-height: 0 !important; transition: none !important; background: transparent;
  scrollbar-width: none !important; -ms-overflow-style: none !important;
}

/* 展开高度限制 */
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body { padding: 16px 20px 24px !important; opacity: 1; visibility: visible; max-height: 380px !important; overflow-y: auto !important; -webkit-overflow-scrolling: touch; scrollbar-width: none !important; }
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body { padding: 16px 20px 24px !important; opacity: 1; visibility: visible; max-height: 320px !important; overflow-y: auto !important; -webkit-overflow-scrolling: touch; scrollbar-width: none !important; }
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-body { padding: 16px 14px 24px !important; opacity: 1; visibility: visible; max-height: 380px !important; overflow-y: auto !important; -webkit-overflow-scrolling: touch; scrollbar-width: none !important; display: flex !important; flex-direction: column !important; gap: 12px !important; }

/* === 展开边框极其浅淡，决不出现深色 === */
#xt-t1:checked ~ .xt-content .xt-collapse-1,
#xt-t2:checked ~ .xt-content .xt-collapse-2,
#xt-t3:checked ~ .xt-content .xt-collapse-3 {
  z-index: 10; 
  width: 98% !important; 
  margin-left: auto !important; 
  margin-right: auto !important; 
  margin-top: 10px !important; 
  margin-bottom: 10px !important;
  background: rgba(229, 179, 190, 0.06) !important; /* 极清浅暖粉底色 */
  border: 1px solid rgba(229, 179, 190, 0.1) !important; /* 极浅粉色虚化边框 */
  border-left: none !important; 
  box-shadow: 0 4px 16px rgba(90, 68, 74, 0.02); 
  transform: translateY(0px) !important; 
  border-radius: 6px 6px 0 0 !important;
  clip-path: polygon(0% 0%, 100% 0%, 100% 96%, 98% 98%, 96% 95%, 94% 97%, 92% 94%, 90% 96%, 88% 94%, 86% 97%, 84% 95%, 82% 97%, 80% 94%, 78% 96%, 76% 94%, 74% 97%, 72% 94%, 70% 96%, 68% 94%, 66% 97%, 64% 94%, 62% 96%, 60% 94%, 58% 97%, 56% 94%, 54% 96%, 52% 94%, 50% 97%, 48% 94%, 46% 96%, 44% 94%, 42% 97%, 40% 94%, 38% 96%, 36% 94%, 34% 97%, 32% 94%, 30% 96%, 28% 94%, 26% 97%, 24% 94%, 22% 96%, 20% 94%, 18% 97%, 16% 94%, 14% 96%, 12% 94%, 10% 97%, 8% 94%, 6% 96%, 4% 94%, 2% 97%, 0% 94%) !important;
}

/* === 全无缝拼图拼接 === */
#xt-t1:checked ~ #xt-t2:checked ~ .xt-content .xt-collapse-2 { margin-bottom: 0px !important; clip-path: none !important; border-bottom: none !important; }
#xt-t1:checked ~ #xt-t2:checked ~ .xt-content .xt-collapse-1 { margin-top: 0px !important; border-top: none !important; border-radius: 0px !important; }
#xt-t1:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-1 { margin-bottom: 0px !important; clip-path: none !important; border-bottom: none !important; }
#xt-t1:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-3 { margin-top: 0px !important; border-top: none !important; border-radius: 0px 0px 0 0 !important; }
#xt-t1:not(:checked) ~ #xt-t2:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-2 { margin-bottom: 0px !important; clip-path: none !important; border-bottom: none !important; }
#xt-t1:not(:checked) ~ #xt-t2:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-3 { margin-top: 0px !important; border-top: none !important; border-radius: 0px 0px 0 0 !important; }
#xt-t1:checked ~ #xt-t2:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-2 { margin-bottom: 0px !important; clip-path: none !important; border-bottom: none !important; border-radius: 6px 6px 0 0 !important; }
#xt-t1:checked ~ #xt-t2:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-1 { margin-top: 0px !important; margin-bottom: 0px !important; border-top: none !important; border-bottom: none !important; border-radius: 0px !important; clip-path: none !important; }
#xt-t1:checked ~ #xt-t2:checked ~ #xt-t3:checked ~ .xt-content .xt-collapse-3 { margin-top: 0px !important; border-top: none !important; border-radius: 0px 0px 0 0 !important; }

/* === 恢复底栏完整字母衬底并精密对齐底边 === */
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body::after,
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-body::after,
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body::after,
#xt-t4:checked ~ .xt-content .xt-collapse-4 .xt-collapse-body::after {
  content: "F R A G M E N T S   O F   T I M E \A A   B   C   D   E   F   G   H   I   J \A 0  4  _  B L U E  _  S P A C E" !important;
  position: absolute !important; 
  bottom: 6px !important; 
  right: 16px !important; 
  font-family: 'Space Mono', monospace !important; 
  font-size: 8px !important; 
  color: rgba(229, 179, 190, 0.14) !important; 
  white-space: pre !important; 
  line-height: 1.4 !important; 
  letter-spacing: 1px !important; 
  pointer-events: none !important; 
  z-index: 0 !important;
}

/* === 见字如面卡片：更替为您指定的柔粉双相纸 === */
.xt-collapse-1 .xt-image { background: transparent !important; border: none !important; padding: 0 !important; margin: 12px auto 28px !important; width: 100% !important; height: 110px !important; position: relative; z-index: 1; }
/* 下层底片：更换为 G9Skjs25 */
.xt-collapse-1 .xt-image img { width: 80px !important; height: 100px !important; object-fit: cover !important; background: #ffffff !important; padding: 4px 4px 12px 4px !important; border: 1px solid rgba(0, 0, 0, 0.04) !important; box-shadow: 1px 6px 12px rgba(0, 0, 0, 0.05) !important; transform: rotate(-10deg) !important; position: absolute !important; left: 18% !important; top: 10px !important; z-index: 3 !important; opacity: 0.95; content: url('https://i.postimg.cc/G9Skjs25/quality-restoration-20260802202153827.jpg') !important; }
/* 上层顶片：更换为 23X4xBy1 */
.xt-collapse-1 .xt-image::after { content: "" !important; position: absolute !important; right: 18% !important; top: 0px !important; width: 80px !important; height: 100px !important; background: url('https://i.postimg.cc/23X4xBy1/quality-restoration-20260802202539743.jpg') center/cover no-repeat, #ffffff !important; border-width: 4px 4px 12px 4px !important; border-style: solid !important; border-color: #ffffff !important; box-shadow: 2px 8px 16px rgba(229, 179, 190, 0.12) !important; transform: rotate(10deg) !important; z-index: 4 !important; outline: 1px solid rgba(0, 0, 0, 0.04); }
.xt-collapse-1 .xt-image::before { content: "" !important; position: absolute !important; right: 26% !important; top: -6px !important; width: 30px; height: 10px; background: rgba(229, 179, 190, 0.5) !important; transform: rotate(25deg) !important; z-index: 5 !important; clip-path: polygon(5% 0%, 95% 0%, 100% 50%, 95% 100%, 5% 100%, 0% 50%); }

/* ====================================================
   🔥 完全恢复您第一版的多轨24重坐标心情文字叠影排版样式 (全部重构为温柔温润的柔粉色) ===
==================================================== */
