/* 信笺信纸 */
.xt-collapse-1 .xt-quote { background: transparent !important; border: none !important; padding: 0 !important; margin-top: 24px !important; font-size: 12.5px !important; line-height: 24px !important; color: var(--xt-text); font-family: "ToneOZ-Tsuipita-TC", var(--xt-font) !important; font-weight: normal !important; text-align: justify; display: block !important; position: relative; z-index: 1; background-image: repeating-linear-gradient(transparent, transparent 23px, rgba(229, 179, 190, 0.12) 23px, rgba(229, 179, 190, 0.12) 24px) !important; }
.xt-collapse-1 .xt-quote::before, .xt-collapse-1 .xt-quote::after { content: "" !important; display: none !important; }

/* === 微信对话模拟 === */
.xt-collapse-2 .xt-text { font-size: 11.5px !important; line-height: 1.6; color: var(--xt-text); letter-spacing: 0.5px; text-align: justify; position: relative; z-index: 1; white-space: pre-wrap !important; }
.xt-text-talk1, .xt-text-talk3, .xt-text-talk5 { align-self: flex-start !important; position: relative !important; margin: 10px 18% 10px 12px !important; width: fit-content !important; max-width: 82% !important; background: rgba(255, 255, 255, 0.85) !important; border: 1px solid rgba(229, 179, 190, 0.12) !important; border-radius: 8px !important; padding: 8px 12px !important; color: var(--xt-text) !important; font-size: 11.5px !important; line-height: 1.5 !important; z-index: 5 !important; box-shadow: 0 1px 4px rgba(229, 179, 190, 0.05) !important; text-align: left !important; display: block !important; }
.xt-text-talk1::first-line, .xt-text-talk3::first-line, .xt-text-talk5::first-line { font-size: 9.5px !important; color: var(--xt-accent) !important; font-weight: 600 !important; letter-spacing: 0.5px !important; }
.xt-text-talk2, .xt-text-talk4, .xt-text-talk6 { align-self: flex-end !important; position: relative !important; margin: 10px 12px 10px auto !important; width: fit-content !important; max-width: 82% !important; background: rgba(229, 179, 190, 0.15) !important; border: 1px solid rgba(255, 255, 255, 0.2) !important; border-radius: 8px !important; padding: 8px 12px !important; color: var(--xt-text) !important; font-size: 11.5px !important; line-height: 1.5 !important; z-index: 5 !important; box-shadow: 0 1px 4px rgba(0, 0, 0, 0.01) !important; text-align: left !important; display: block !important; }
.xt-text-talk2::first-line, .xt-text-talk4::first-line, .xt-text-talk6::first-line { font-size: 9.5px !important; color: var(--xt-text-sub) !important; font-weight: 600 !important; letter-spacing: 0.5px !important; }

/* === 浮生琐记 === */
.xt-list-check { display: none !important; }
.xt-list { display: flex !important; flex-direction: column !important; gap: 8px !important; height: auto !important; width: 100% !important; margin-top: 8px !important; margin-bottom: 5px !important; position: relative !important; }
.xt-list-item { 
  position: relative !important; transform: none !important; opacity: 1 !important; z-index: 1 !important; left: 0 !important; top: 0 !important; width: 100% !important; height: auto !important; box-sizing: border-box !important; 
  padding: 8px 12px 8px 20px !important; 
  border-radius: 6px !important; 
  background: rgba(255, 255, 255, 0.45) !important; /* 极清透白沙色底 */
  border: 1px dashed rgba(229, 179, 190, 0.12) !important; /* 极细淡暖粉虚线 */
  outline: 1px dashed rgba(229, 179, 190, 0.04) !important; 
  outline-offset: -2px !important; 
  box-shadow: 0 1px 4px rgba(229, 179, 190, 0.01) !important; 
  transition: all 0.3s ease !important; display: block !important; 
  font-family: "Xiaolai Mono", monospace !important;
  font-weight: normal !important;
}
.xt-list-item:hover { background: rgba(255, 255, 255, 0.6) !important; border-color: rgba(229, 179, 190, 0.25) !important; }
.xt-list-item::before { content: "▫" !important; font-family: monospace !important; font-size: 8px !important; color: var(--xt-accent) !important; position: absolute !important; left: 8px !important; top: 10px !important; display: inline-block !important; font-weight: bold !important; }
.xt-list-item::after { content: "" !important; position: absolute !important; top: -4px !important; left: 15% !important; width: 20px !important; height: 5px !important; background: rgba(229, 179, 190, 0.12) !important; transform: rotate(-1deg) !important; pointer-events: none !important; border-radius: 1px !important; display: block !important; z-index: 2 !important; }

/* 强制列表文字极小（8.5px），配色改写为极其清浅、接近白沙且融于背景的超淡粉色（#f2e1e3） */
.xt-list-text { 
  font-family: "Xiaolai Mono", monospace !important; 
  font-weight: normal !important;
  font-size: 8.5px !important; 
  line-height: 1.6 !important; 
  color: #f2e1e3 !important; /* 精准重设为极其浅淡清秀的微风粉，彻底避免深重色 */
  text-align: justify !important; display: block !important; 
}

/* === Ⅳ区（论坛面板控制） === */
.xt-collapse-4 { display: none !important; }
.xt-collapse-4 .xt-collapse-header { display: none !important; }

/* ====================================================
   🔥 右下角：虚实重叠双圆环 (下移贴边) ===
==================================================== */
.xt-action-4 {
  display: block !important; 
  position: absolute !important; 
  bottom: -4px !important; 
  right: 25px !important;
  width: 18px !important;
  height: 18px !important;
  border: 1.2px solid rgba(229, 179, 190, 0.25) !important; 
  border-radius: 50% !important;
  background: rgba(253, 245, 246, 0.3) !important; 
  cursor: pointer !important;
  z-index: 9999 !important;
  color: transparent !important;
  font-size: 0 !important;
  transition: all 0.4s ease !important;
}

.xt-action-4::before {
  content: "" !important;
  display: block !important; 
  position: absolute !important;
  width: 18px !important;
  height: 18px !important;
  border: 1.2px solid rgba(229, 179, 190, 0.2) !important;
  border-radius: 50% !important;
  background: rgba(253, 245, 246, 0.15) !important;
  top: -4px !important;
  left: -8px !important; 
  transition: all 0.4s ease !important;
}

.xt-action-4::after {
  display: none !important;
}

.xt-action-4:hover { transform: scale(1.05) !important; }

/* ====================================================
   🔥 论坛被点开状态 ===
==================================================== */
#xt-t4:checked ~ .xt-content .xt-collapse-1,
#xt-t4:checked ~ .xt-content .xt-collapse-2,
#xt-t4:checked ~ .xt-content .xt-collapse-3,
#xt-t4:checked ~ .xt-content::after {
  display: none !important;
}

#xt-t4:checked ~ .xt-content .xt-collapse-4 {
  display: block !important;
  z-index: 100;
  width: 98% !important; 
  margin: 10px auto !important;
  background: rgba(255, 255, 255, 0.4) !important;
  border: 1px solid rgba(229, 179, 190, 0.15) !important; 
  box-shadow: 0 8px 30px rgba(229, 179, 190, 0.08) !important;
  border-radius: 12px !important;
  padding: 16px 8px !important;
  backdrop-filter: blur(4px) !important;
  -webkit-backdrop-filter: blur(4px) !important;
}

#xt-t4:checked ~ .xt-content .xt-collapse-4 .xt-collapse-body {
  padding: 12px 6px 20px !important;
  opacity: 1 !important;
  visibility: visible !important;
  max-height: 400px !important; 
  overflow-y: auto !important;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 14px !important;
}

/* 叠环点击动作 */
#xt-t4:checked ~ .xt-content .xt-action-4 {
  background: rgba(229, 179, 190, 0.15) !important;
  border-color: rgba(229, 179, 190, 0.4) !important;
  transform: scale(0.95) rotate(45deg) !important;
}
#xt-t4:checked ~ .xt-content .xt-action-4::before {
  left: -4px !important;
  top: -2px !important;
  border-color: rgba(229, 179, 190, 0.3) !important;
}

/* ====================================================
   🔥 论坛跟帖排版 ===
==================================================== */
#xt-t4:checked ~ .xt-content .xt-collapse-4 .xt-collapse-body::before {
  content: "" !important;
  display: none !important;
}

/* ==================== 1. 楼主主帖 ==================== */
.xt-text-forum_post_1 {
  background: rgba(255, 255, 255, 0.92) !important;
  border: 1px solid rgba(229, 179, 190, 0.18) !important;
  border-radius: 12px !important;
  padding: 12px 14px !important; 
  font-size: 11px !important; 
  line-height: 1.6 !important;
  color: var(--xt-text) !important;
  position: relative !important;
  margin: 0 0 8px 0 !important;
  text-align: left !important;
  box-shadow: 0 4px 12px rgba(229, 179, 190, 0.04) !important;
  display: block !important;
}

.xt-text-forum_post_1::before {
  display: none !important;
}

.xt-text-forum_post_1::first-line {
  font-size: 11px !important; 
  color: var(--xt-accent) !important;
  font-weight: 600 !important;
  letter-spacing: 0.5px !important;
  line-height: 1.8 !important;
}

.xt-text-forum_post_1::after {
  content: "楼主" !important;
  position: absolute !important;
  top: 12px !important;
  right: 14px !important;
  background: var(--xt-accent) !important;
  color: #ffffff !important;
  font-size: 8px !important;
  font-weight: bold !important;
  padding: 2px 6px !important;
  border-radius: 4px !important;
}

/* ==================== 2. 下方层叠回帖流 ==================== */
.xt-text-forum_reply_1, 
.xt-text-forum_reply_2, 
.xt-text-forum_reply_3, 
.xt-text-forum_reply_4, 
.xt-text-forum_reply_5 {
  background: rgba(255, 255, 255, 0.65) !important;
  border: none !important;
  border-bottom: 1px dashed rgba(229, 179, 190, 0.15) !important;
  border-radius: 0px !important;
  padding: 12px 14px !important; 
  font-size: 11px !important; 
  line-height: 1.5 !important;
  color: var(--xt-text) !important;
  position: relative !important;
  margin: 0 !important;
  text-align: left !important;
  display: block !important;
}

.xt-text-forum_reply_1::before, 
.xt-text-forum_reply_2::before, 
.xt-text-forum_reply_3::before, 
.xt-text-forum_reply_4::before, 
.xt-text-forum_reply_5::before {
  display: none !important;
}

.xt-text-forum_reply_1::after, 
.xt-text-forum_reply_2::after, 
.xt-text-forum_reply_3::after, 
.xt-text-forum_reply_4::after, 
.xt-text-forum_reply_5::after {
  display: none !important;
}

.xt-text-forum_reply_1::first-line, 
.xt-text-forum_reply_2::first-line, 
.xt-text-forum_reply_3::first-line, 
.xt-text-forum_reply_4::first-line, 
.xt-text-forum_reply_5::first-line {
  font-size: 11px !important; 
  color: var(--xt-text-sub) !important;
  font-weight: 600 !important;
  line-height: 1.8 !important;
}

.xt-text-forum_reply_1 .xt-reply-floor, .xt-text-forum_reply_1::after { content: "#1" !important; position: absolute !important; top: 12px !important; right: 14px !important; font-family: var(--xt-font) !important; font-size: 9px !important; color: var(--xt-text-sub) !important; opacity: 0.6; }
.xt-text-forum_reply_2 .xt-reply-floor, .xt-text-forum_reply_2::after { content: "#2" !important; position: absolute !important; top: 12px !important; right: 14px !important; font-family: var(--xt-font) !important; font-size: 9px !important; color: var(--xt-accent) !important; opacity: 0.9; font-weight: bold; }
.xt-text-forum_reply_3 .xt-reply-floor, .xt-text-forum_reply_3::after { content: "#3" !important; position: absolute !important; top: 12px !important; right: 14px !important; font-family: var(--xt-font) !important; font-size: 9px !important; color: var(--xt-text-sub) !important; opacity: 0.6; }
.xt-text-forum_reply_4 .xt-reply-floor, .xt-text-forum_reply_4::after { content: "#4" !important; position: absolute !important; top: 12px !important; right: 14px !important; font-family: var(--xt-font) !important; font-size: 9px !important; color: var(--xt-text-sub) !important; opacity: 0.6; }
.xt-text-forum_reply_5 .xt-reply-floor, .xt-text-forum_reply_5::after { content: "#5" !important; position: absolute !important; top: 12px !important; right: 14px !important; font-family: var(--xt-font) !important; font-size: 9px !important; color: var(--xt-text-sub) !important; opacity: 0.6; }

.xt-text-forum_reply_2 {
  background: rgba(229, 179, 190, 0.14) !important; 
  border-left: 2px solid var(--xt-accent) !important; 
}

/* === 滚动条完全透明 === */
::-webkit-scrollbar { width: 0px !important; height: 0px !important; background: transparent !important; }
::-webkit-scrollbar-thumb { background: transparent !important; }
::-webkit-scrollbar-track { background: transparent !important; }

xinshengLayout:
# 雾语蓝 - 渐变叠影论坛版
@particles rain 30

@collapse "Ⅱ ． 隙 间 白 噪" 2 .fadeInUp.delay100
@text talk1
@text talk2
@text talk3
@text talk4
@text talk5
@text talk6
@endcollapse

@collapse "Ⅰ ． 见 字 如 面" 1 .fadeInUp.delay200
@image letterImage
@text moodWord1
@text moodWord2
@text moodWord3
@quote letterConfession
@endcollapse

@collapse "Ⅲ ．  浮 生 瑣 記" 3 .fadeInUp.delay300
@list
memo1
memo2
memo3
@endcollapse

# === 隐藏论坛区 (1个主帖 + 5个顺序评论流) ===
@collapse "Ⅳ ． 雾 境 坛 喧" 4
@text forum_post_1
@text forum_reply_1
@text forum_reply_2
@text forum_reply_3
@text forum_reply_4
@text forum_reply_5
@endcollapse

# === 右下角交互开关 ===
@toggle 4

